using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class BEONavGrid {
 public static object Run(){string repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));var p=JObject.Parse(File.ReadAllText(repo+"/SourceAssets/B4_ExperimentOperations/layout.json"));var rows=new List<object>();var player=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var cc=player.GetComponent<CharacterController>();bool enabled=cc.enabled;cc.enabled=false;
 try{foreach(var r in p["rooms"].Where(q=>new[]{"C05","W01","E02","E03"}.Contains((string)q["id"]))){float radius=(float)r["r"],cell=.20f;int n=Mathf.CeilToInt(2*radius/cell)+1;var c=new Vector3((float)r["x"],-66,-(float)r["v"]);var valid=new List<int>();for(int i=0;i<n*n;i++){var v=c+new Vector3(-radius+(i%n)*cell,0,-radius+(i/n)*cell);if((v-c).sqrMagnitude>Mathf.Pow(radius-.12f,2))continue;if(!Physics.Raycast(v+Vector3.up*.30f,Vector3.down,out var h,.55f,~0,QueryTriggerInteraction.Ignore)||h.point.y<v.y-.1f)continue;if(!Physics.CheckCapsule(v+Vector3.up*.43f,v+Vector3.up*1.5f,.32f,~0,QueryTriggerInteraction.Ignore))valid.Add(i);}rows.Add(new{room=(string)r["id"],radius,cell,n,valid});}}finally{cc.enabled=enabled;}
 File.WriteAllText(repo+"/SourceAssets/B4_ExperimentOperations/nav_grid.json",JsonConvert.SerializeObject(rows));return new{rooms=rows.Count};}
}
